// Node-side stand-in for `@tanstack/react-start/server-entry`, aliased for the unit project in
// apps/os/vitest.config.ts. Start's server entry is generated by the Vite build and does not exist in
// plain node; the edge's routing rows (worker.test.ts) need only an issuer page that answers, with no
// `vi.mock` in the test file (iterate/no-vi-mock). It proves nothing about Start itself: the built
// worker's suites (__workers-tests__/, the browser specs) run the real entry.

export default {
  fetch: () => new Response("<html>Issuer page</html>", { status: 200 }),
};
